<script setup lang="ts">
import {computed} from 'vue'
import {useStudio} from './studioContext'
import EntityActions from './EntityActions.vue'
import AppIcon from './AppIcon.vue'
const props=defineProps<{characterId:string}>(),s=useStudio()
const r=computed(()=>s.rec('persona',props.characterId)),presets=['爽朗直接','沉稳克制','温和谨慎','机敏含蓄']
const scopeCount=computed(()=>r.value?.draft.knowledgeTiming?.filter((v:any)=>v.status==='known'||v.access==='assumed').length||0)
async function adopt(){await s.run(async()=>{await s.saveAll();await s.legacy(await s.api(`/projects/${s.p.value.id}/studio/personas/${props.characterId}/adopt-suggestion`,'POST',{version:s.p.value.version,kind:'persona',id:props.characterId}))});await s.applyRecord(s.rec('persona',props.characterId))}
</script>
<template><article v-if="r" class="persona-editor" :data-entity-key="'persona:'+characterId" aria-label="入画角色设定"><div class="rail-heading"><h2>入画角色设定</h2></div><p class="muted">称谓与性格按身份自动填写，属于可修改的演绎设定。选项中的自称、性格优先于整体设定中的旧表述。时间视角全项目统一，知识范围自动处理。</p><fieldset :disabled="s.locked('persona',characterId)"><div class="persona-options"><label>自称<input v-model="r.draft.selfReference" placeholder="自动按身份选择"></label><label>性格<select :value="presets.includes(r.draft.temperament)?r.draft.temperament:'custom'" @change="r.draft.temperament=($event.target as HTMLSelectElement).value==='custom'?'':($event.target as HTMLSelectElement).value"><option v-for="v in presets">{{v}}</option><option value="custom">自定义</option></select></label><input v-if="!presets.includes(r.draft.temperament)" aria-label="自定义性格" v-model="r.draft.temperament"></div><label>整体角色设定<textarea v-model="r.draft.prompt" rows="7" placeholder="使用页首生成角色设定，也可直接填写"/></label><small>自动准备 {{scopeCount}} 条可用线索；暂无线索也能按身份交谈，不补编历史事实。</small><EntityActions :record="r"/><details><summary>来源、自动知识判断与高级调整</summary><p>{{r.draft.historicalBoundary}}</p><p>{{r.draft.situation}}</p><div v-for="row in r.draft.knowledgeTiming" :key="row.clueId"><b>{{s.rec('clue',row.clueId)?.published?.name||row.clueId}}</b><small>{{row.access==='assumed'?'AI推定知晓':row.status==='known'?'可知':row.status==='after'?'后续事件，已排除':'待考'}} · {{row.reason}}</small></div><details v-if="r.suggestion"><summary>另一个角色建议</summary><pre>{{r.suggestion.prompt}}</pre><button @click="adopt">使用此建议</button></details><button :disabled="s.busy.value||s.generating.value" @click="s.generate('persona',characterId)"><AppIcon name="ai" :size="14"/>重新生成此人物设定</button></details></fieldset></article></template>
<style scoped>.persona-editor fieldset{min-width:0;border:0;padding:0}.persona-editor p,.persona-editor small{font-size:12px;line-height:1.8;color:#748079}.persona-editor small{display:block}.persona-editor details{margin-top:16px;font-size:12px}.persona-editor details>div{padding:10px 0;border-bottom:1px solid #e3e8e3}.persona-editor pre{white-space:pre-wrap}.persona-options{display:flex;gap:14px;align-items:flex-end;margin-bottom:15px}.persona-options label{flex:1;max-width:220px}.persona-options input{max-width:220px}.persona-editor{scroll-margin-top:110px}</style>
